return $input.all().map((item, i) => {
  const src = $('Merge1').itemMatching(i).json;
  const raw = String(item.json.text || item.json.output || item.json.response || '').replace(/^\s*```(?:json)?\s*|\s*```\s*$/gi, '').trim();
  const review = (error) => ({
    json: { ...src, job_url: src.url, job_title: src.title, company: src.companyName || '',
      score: null, recommendation: 'REVIEW', parse_error: true, error },
    pairedItem: { item: i },
  });
  let p;
  try { p = JSON.parse(raw); } catch { return review('Invalid scoring JSON'); }
  if (!p || typeof p.score !== 'number' || !Number.isInteger(p.score) || p.score < 0 || p.score > 100) {
    return review('Invalid score');
  }
  let eligibility_status = p.eligibility_status;
  let eligibility_reason = p.eligibility_reason || '';
  // Existing local work-rights requirements need country-specific confirmation.
  if (/full\s+working\s+rights\s+in\s+the\s+country\s+of\s+application/i.test(src.description || '') && eligibility_status !== 'blocked') {
    eligibility_status = 'needs_review';
    eligibility_reason = 'Explicit full working-rights requirement; confirm eligibility and any sponsorship exception with the employer.';
  }
  if (!['clear', 'blocked', 'needs_review'].includes(eligibility_status)) {
    eligibility_status = 'needs_review';
    eligibility_reason = 'Eligibility assessment is missing or invalid.';
  }
  const recommendation = eligibility_status === 'blocked' ? 'SKIP'
    : eligibility_status === 'needs_review' ? 'REVIEW'
    : p.score >= 75 ? 'APPLY' : p.score >= 55 ? 'CONSIDER' : 'SKIP';
  return { json: {
    ...src, ...p, score: p.score, recommendation, eligibility_status, eligibility_reason, parse_error: false,
    id: src.id, job_url: src.url, job_title: src.title, company: src.companyName || '',
    location: src.location || '', description: src.description || '',
    master_profile: src.master_profile, base_cvs: src.base_cvs,
  }, pairedItem: { item: i } };
});

const ranked = $input.all().map((item, i) => ({ item, i }))
  .filter(({ item }) => !item.json.parse_error && item.json.score >= 55 && ['APPLY', 'CONSIDER'].includes(item.json.recommendation))
  .sort((a, b) => b.item.json.score - a.item.json.score);
return ranked.slice(0, 10).map(({ item, i }) => ({ json: item.json, pairedItem: { item: i } }));

const items = $input.all();
const profile = items.find(item => typeof item.json.data === 'string' && item.json.data.includes('MASTER PROFILE'));
const master_profile = (profile?.json.data || '').split('## 🇪🇸')[0].trim();
const base_cvs = items.flatMap((item, i) => {
  if (typeof item.json.text !== 'string' || !item.json.text.trim()) return [];
  const file = $('Download file').itemMatching(i).json;
  return [{ filename: file.name || item.json.info?.Title, content: item.json.text.trim() }];
});
if (!master_profile || !base_cvs.length || base_cvs.some(cv => !cv.filename)) {
  throw new Error('Missing master profile, readable CV text, or CV filename in the Profile folder.');
}
return [{ json: { master_profile, base_cvs } }];

const results = [];

for (const [i, item] of $input.all().entries()) {
  const src = $('Code in JavaScript1').itemMatching(i).json;
  let raw = item.json.text || item.json.output || item.json.response || '';
  raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

  const date = $now.setZone('Europe/Madrid').toISODate();

  try {
    const p = JSON.parse(raw);
    if (!p || typeof p !== 'object' || Array.isArray(p)) throw new Error('Expected a CV recommendation object');
    if (!src.base_cvs.some(cv => cv.filename === p.chosen_cv)) throw new Error('Unknown chosen CV: ' + p.chosen_cv);
    for (const field of ['keywords_to_add', 'bullets_to_emphasize', 'do_not_claim', 'adaptations']) {
      if (!Array.isArray(p[field])) throw new Error('Invalid array: ' + field);
    }
    Object.assign(p, { job_url: src.job_url, job_title: src.job_title, company: src.company, score: src.score, recommendation: src.recommendation });

    const safe = (s) => String(s || 'x').replace(/[^\w\-]+/g, '_').slice(0, 40);
    const jobId = String(src.id || src.job_url.match(/\d+(?:[/?#]|$)/)?.[0] || '').replace(/\D/g, '');
    const fileName = `${date}_${safe(p.company)}_${safe(p.job_title)}${jobId ? '_' + jobId : ''}.md`;

    const adaptationsText = Array.isArray(p.adaptations)
      ? p.adaptations.map((a, i) => `${i + 1}. [${a.section}/${a.action}] ${a.detail}`).join('\n')
      : String(p.adaptations || '');

    const content = `# ${p.job_title || ''} @ ${p.company || ''}

- Date: ${date}
- Score: ${p.score} (${p.recommendation || ''})
- Priority: ${p.priority || ''}
- URL: ${p.job_url || ''}
- Chosen CV: ${p.chosen_cv || ''}

## Positioning
${p.target_positioning || ''}

## Profile rewrite
${p.profile_rewrite || ''}

## Why this CV
${p.why_this_cv || ''}

## Adaptations
${adaptationsText}

## Keywords
${(p.keywords_to_add || []).join(' | ')}

## Emphasize
${(p.bullets_to_emphasize || []).join(' | ')}

## Do not claim
${(p.do_not_claim || []).join(' | ')}

## Application notes
${p.application_notes || ''}
`;

    results.push({
      json: {
        date,
        job_url: p.job_url || '',
        job_title: p.job_title || '',
        company: p.company || '',
        score: Number(p.score) || 0,
        recommendation: p.recommendation || '',
        priority: p.priority || '',
        chosen_cv: p.chosen_cv || '',
        secondary_cv: p.secondary_cv || '',
        why_this_cv: p.why_this_cv || '',
        target_positioning: p.target_positioning || '',
        profile_rewrite: p.profile_rewrite || '',
        adaptations: adaptationsText,
        keywords_to_add: (p.keywords_to_add || []).join(' | '),
        bullets_to_emphasize: (p.bullets_to_emphasize || []).join(' | '),
        do_not_claim: (p.do_not_claim || []).join(' | '),
        application_notes: p.application_notes || '',
        fileName,
        status: 'to_apply',
        parse_error: false,
      },
      pairedItem: { item: i },
      binary: {
        data: {
          data: Buffer.from(content, 'utf8').toString('base64'),
          mimeType: 'text/markdown',
          fileName,
        },
      },
    });
  } catch (e) {
    throw new Error('Invalid CV recommendation for ' + src.job_url + ': ' + e.message);
  }
}

return results;

const rows = $input.all().map(item => item.json).filter(row => row.job_url && row.company);
const invalid = $('Code in JavaScript').all().filter(item => item.json.parse_error);
const warning = invalid.length
  ? '

Scoring warnings: ' + invalid.length + ' offers need review (invalid AI output):
' + invalid.map(item => item.json.job_url).join('
')
  : '';
const date = $now.setZone('Europe/Madrid').toISODate();
const lines = rows.map((r, i) => `${i + 1}. ${r.company} — ${r.job_title} | ${r.score} (${r.recommendation})
${r.job_url}
${String(r.fileName || '').replace(/^=HYPERLINK\("([^"]+)","([^"]+)"\)$/, '$2
$1')}`).join('

');
return [{ json: {
  subject: `Job Automation — ${date} — ${rows.length} offers`,
  body: `Hello,

Today's shortlist (${rows.length}):

${lines || '(no offers)'}${warning}

MD files: Drive → Job Automation → Applications
Sheet updated.

— n8n`,
} }];

const key = (value) => {
  const url = String(value || '').trim().replace(/[?#].*$/, '').replace(/\/$/, '');
  if (!/^https?:\/\//i.test(url)) return '';
  const linkedIn = /^https?:\/\/(?:[a-z0-9-]+\.)?linkedin\.com\//i.test(url);
  const id = linkedIn && url.match(/\/jobs\/view\/(?:[^/]*-)?(\d+)$/i);
  return id ? 'linkedin:' + id[1] : url;
};
const seen = new Set($('Read existing offers').all()
  .filter(item => item.json.status !== 'error')
  .map(item => key(item.json.job_url)).filter(Boolean));
const results = [];
for (const [i, item] of $input.all().entries()) {
  const job = item.json;
  const id = key(job.url);
  if (!id || !job.title || seen.has(id)) continue;
  if (/\b(senior|sr\.?|lead|principal|director|head|staff|manager)\b/i.test(job.title)) continue;
  seen.add(id);
  results.push({ json: job, pairedItem: { item: i } });
}
return results;
